use std :: collections :: HashMap ; use std :: sync :: Arc ; use derive_setters :: Setters ; use forge_domain :: { Agent , Conversation , Environment , Extension , ExtensionStat , File , Model , SystemContext , Template , TemplateConfig , ToolCatalog , ToolDefinition , ToolUsagePrompt , } ; use serde_json :: { Map , Value , json } ; use strum :: IntoEnumIterator ; use tracing :: debug ; use crate :: { ShellService , SkillFetchService , TemplateEngine } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Parses the newline-separated output of `git ls-files` into an [`Extension`]"] # [doc = " summary."] fn parse_extensions (extensions : & str , max_extensions : usize) -> Option < Extension > { let all_files : Vec < & str > = extensions . lines () . map (str :: trim) . filter (| line | ! line . is_empty ()) . collect () ; let total_files = all_files . len () ; if total_files == 0 { return None ; } let mut counts = HashMap :: < & str , usize > :: new () ; all_files . iter () . map (| line | { let file_name = line . rsplit_once (['/' , '\\']) . map_or (* line , | (_ , f) | f) ; file_name . rsplit_once ('.') . filter (| (prefix , _) | ! prefix . is_empty ()) . map_or ("(no ext)" , | (_ , ext) | ext) }) . for_each (| ext | * counts . entry (ext) . or_default () += 1) ; let mut stats : Vec < _ > = counts . into_iter () . map (| (extension , count) | { let percentage = ((count * 100) as f32 / total_files as f32) . round () as usize ; ExtensionStat { extension : extension . to_owned () , count , percentage : percentage . to_string () , } }) . collect () ; stats . sort_by (| a , b | { b . count . cmp (& a . count) . then_with (| | a . extension . cmp (& b . extension)) }) ; let total_extensions = stats . len () ; stats . truncate (max_extensions) ; let shown_count : usize = stats . iter () . map (| s | s . count) . sum () ; let remaining_count = total_files . saturating_sub (shown_count) ; let remaining_percentage = ((remaining_count * 100) as f32 / total_files as f32) . ceil () . to_string () ; Some (Extension { extension_stats : stats , git_tracked_files : total_files , max_extensions , total_extensions , remaining_percentage , }) }